-- Algeria service areas: Algiers, Oran, Annaba.
--
-- Repoints the rider backend from the upstream Indian service areas to
-- Algerian ones. The Indian geometry rows are deliberately left in the table
-- but are no longer referenced by any merchant, so this is reversible.
--
-- How serviceability actually works
-- (rider-app Main/src/Storage/Queries/Geometry.hs, someGeometriesContain):
--
--     SELECT * FROM atlas_app.geometry
--      WHERE region IN (<merchant.origin_restriction>)
--        AND ST_Contains(geom, ST_Point(lon, lat));
--
-- So a "city" here is two pieces of data and zero lines of code:
--   1. a row in atlas_app.geometry  (region name + boundary polygon)
--   2. that region name listed in the merchant's origin/destination restriction
--
-- Adding a fourth city means adding one more row and one more array element.
--
-- Boundaries: OpenStreetMap wilaya relations (admin_level=4) retrieved via
-- Nominatim, then simplified with ST_SimplifyPreserveTopology at 0.0005 deg
-- (~55 m) to keep this file reviewable -- 33k points down to 2.6k. That is far
-- finer than a taxi service area needs. Spot-checked against city centres and
-- the Algiers and Oran airports; Constantine correctly falls outside.
--   Algiers  OSM relation 157062
--   Oran     OSM relation 1259187
--   Annaba   OSM relation 1455599
--   (c) OpenStreetMap contributors, ODbL.
--
-- SRID is 0, not 4326, to match the existing rows and the ST_Point() that the
-- application builds -- PostGIS refuses ST_Contains across mismatched SRIDs.
--
-- Idempotent: safe to re-run.
--
-- NOTE: the merchant record is cached in Redis
-- (Main/src/Storage/CachedQueries/Merchant.hs), so after applying this the
-- cache must be dropped or the API keeps using the old service areas:
--     docker exec ny-redis redis-cli FLUSHALL
-- setup.sh does this automatically.

BEGIN;

DELETE FROM atlas_app.geometry WHERE region IN ('Algiers', 'Oran', 'Annaba');

INSERT INTO atlas_app.geometry (id, region, geom) VALUES
